        function chrome(content) { return `<div class="layout"><aside class="side"><div class="side-mark"><span class="loop">∞</span></div><div class="side-scroll">${nav.map(navItem).join('')}<div class="nav-divider"></div><button class="side-item ${state.route === 'journey' ? 'active' : ''}" data-route="journey" title="Customer journey">${icon('sparkle')}<span>Journey</span></button></div><div class="side-footer">IDLE<br>DEMO</div></aside><div class="app"><header class="topbar"><button class="brand" data-route="home" aria-label="IDLE homepage"><img src="${FALLBACK.logo}" alt="IDLE official wordmark"></button><form class="header-search" id="header-search">${icon('search')}<input id="global-search" autocomplete="off" aria-label="Search marketplace" placeholder="Search items, services, rentals or people…" value="${esc(state.search)}"></form><div class="header-loc">${icon('pin')} North Texas <span class="muted">· Demo</span></div><div class="header-actions"><button class="icon-btn" title="Tools & resources" data-route="resources" aria-label="Tools and resources">${icon('grid')}</button>${!state.joined ? `<button class="btn outline join-chip" data-route="onboarding">Join IDLE</button>` : ``}<button class="user-chip" data-route="profile"><span class="user-avatar">${esc(state.name.slice(0, 1).toUpperCase())}</span>${esc(state.name)}</button><button class="btn gold" data-route="post">${icon('plus')} <span>Post</span></button></div></header>${content}</div></div>${mobileNav()}<div id="toast-area" class="toast-area" aria-live="polite"></div>` }
        function storiesStrip() { return `<div class="section"><div class="section-head"><div><div class="eyebrow">Local discovery</div><h2><span class="accent-mark"></span>Nearby Reels</h2><p>See the people and items behind marketplace listings. Sample neighborhoods, not live geolocation.</p></div><button class="link" data-route="reels">View all Reels →</button></div><div class="stories-strip" role="group" aria-label="Nearby Reel stories">${stories().map((r, i) => `<button class="story-bubble" data-reel="${esc(r.id)}" aria-label="Open Reel ${esc(r.title)}"><span class="story-ring ${r.source === 'user' ? 'story-live-ring' : ''}">${r.media ? `<img src="${r.media}" alt="">` : images(r.image, 'alt=""')}</span><strong>${esc(r.category)}</strong><small>${r.source === 'user' ? '24h · Yours' : esc(r.area) + ' · Demo'}</small></button>`).join('')}</div></div>` }
        function categoryTiles() { return `<section class="section"><div class="section-head"><div><div class="eyebrow">Make more possible</div><h2><span class="accent-mark"></span>Shop by category</h2></div><button class="link" data-route="explore">All categories →</button></div><div class="category-grid">${cats.map(([id, title, img, sub]) => `<button class="category-tile" data-category="${id}">${images(img, `alt="${esc(title)}" loading="lazy"`)}<div><strong>${esc(title)}</strong><p>${esc(sub)}</p></div></button>`).join('')}</div></section>` }
        function listingCard(x) { const liked = state.likes.includes(x.id); return `<article class="listing"><button class="listing-main" data-listing="${x.id}" aria-label="View ${esc(x.title)}">${images(x.image, `class="listing-photo" alt="${esc(x.title)}" loading="lazy"`)}<span class="listing-label">${esc(x.tag || 'Local listing')}</span><div class="listing-text"><strong class="listing-title">${esc(x.title)}</strong><div class="listing-price">$${esc(x.price)} <span>/ ${esc(x.unit)}</span></div><div class="listing-meta">${icon('pin', 'inline-icon')} ${esc(x.area)} · North Texas</div><div class="listing-owner"><span>${esc(x.owner)}</span><span class="sample-tag">DEMO</span></div></div></button><button class="bookmark ${liked ? 'saved' : ''}" data-like="${x.id}" aria-label="${liked ? 'Remove favorite' : 'Save favorite'}">${icon('heart')}</button></article>` }
        function featured() { return `<section class="section"><div class="section-head"><div><div class="eyebrow">Curated for discovery</div><h2><span class="accent-mark"></span>Featured near you</h2><p>Illustrative offerings; no live availability or bookings.</p></div><button class="link" data-route="explore">View all →</button></div><div class="listing-grid">${listings.slice(0, 10).map(listingCard).join('')}</div></section>` }
        function promotions() { let panels = [['Enterprise teams', 'Equipment, people and operations in one place', 'enterprise', 'enterprise'], ['Trusted local skills', 'Meet workers and discover nearby services', 'workers', 'Services'], ['Events & experiences', 'Discover people, equipment and spaces', 'events', 'Events']]; return `<section class="section"><div class="feature-panels">${panels.map(([title, text, img, category]) => `<button class="feature-panel" data-category="${esc(category)}">${images(img, `alt="${esc(title)}" loading="lazy"`)}<span class="feature-panel-content"><strong>${esc(title)}</strong><small>${esc(text)}</small><span>Discover more ↗</span></span></button>`).join('')}</div></section>` }
        function home() { return `<section class="hero">${images('hero', 'class="hero-image" alt="Neighbors collaborating"')}<div class="hero-content"><div class="eyebrow" style="color:#e6cd93">The opportunity around you</div><h1>Get more<br>from what<br><em>you own.</em></h1><p>Rent. Lend. Get help. Earn. A marketplace for real things, local skills and useful time.</p><div class="hero-ctas"><button class="btn gold" data-route="explore">Explore marketplace →</button><button class="btn outline" data-route="reels">${icon('play')} Watch Reels</button></div></div><div class="hero-badges"><div>${icon('shield')}<section><strong>Clear marketplace records</strong><span>Agreements and visible transaction steps</span></section></div><div>${icon('users')}<section><strong>People behind the listings</strong><span>Reels, profiles and local categories</span></section></div><div>${icon('building')}<section><strong>Business workflows</strong><span>Enterprise teams, approvals and inventory</span></section></div></div><span class="hero-disclaimer">Illustrative photography · IDLE pre-launch prototype</span></section>${storiesStrip()}${categoryTiles()}${featured()}${promotions()}<section class="section"><div class="panel" style="background:linear-gradient(120deg,#004f46,#0c6559);color:#fff;padding:26px 30px;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap"><div><div class="eyebrow" style="color:#e6c983">Make your next move</div><h2 style="font:600 32px var(--serif);margin:5px 0">Browse free. Earn with Trade.</h2><p style="font-size:12px;color:#e0efe6;margin:0">Browse and post eligible requests for free. Paid memberships unlock communication and earning tools.</p></div><button class="btn gold" data-route="membership">Compare memberships →</button></div></section>` }
        function reelDrawer() { const r = getStory(); if (!r) return ''; const demo = r.source === 'sample'; const lis = r.listingId ? getListing(r.listingId) : null; const image = r.media ? `<img src="${r.media}" alt="${esc(r.title)}">` : images(r.image, `alt="${esc(r.title)}"`); const visual = r.isVideo ? `<video src="${r.media}" controls autoplay loop playsinline muted></video>` : image; return `<div class="reel-stage" role="dialog" aria-label="Reel: ${esc(r.title)}"><div class="progress"><span></span></div>${visual}<div class="reel-gradient"></div><div class="reel-top"><span class="avatar">${esc(r.author[0])}</span><div><strong>${esc(r.author)}</strong><small>${demo ? 'Example story · ' + r.area : 'Your post · 24-hour Reel'}</small></div><button data-close-reel title="Close Reel" aria-label="Close Reel">${icon('x')}</button></div><div class="reel-actions-vertical"><button data-reel-like="${esc(r.id)}" title="Save reel">${icon('heart')}<span>${state.bookmarks.includes(r.id) ? 'Saved' : 'Save'}</span></button><button data-share-reel="${esc(r.id)}" title="Copy Reel details">${icon('message')}<span>Share</span></button></div><div class="reel-bottom"><span class="reel-pill">${esc(r.category)} · ${demo ? 'Illustrative example' : remaining(r.created) + ' remaining'}</span><h3>${esc(r.title)}</h3><p>${esc(r.caption)}</p>${demo ? '<div class="reel-demo-disclaimer">Demonstration story — not a live local Reel</div>' : ''}<div class="reel-controls"><button data-prev-reel title="Previous Reel" aria-label="Previous Reel">${icon('left')}</button><span class="tiny">${stories().findIndex(x => x.id === r.id) + 1} of ${stories().length}</span><button data-next-reel title="Next Reel" aria-label="Next Reel">${icon('chevron')}</button></div>${lis ? `<button class="btn green" data-listing="${lis.id}">View listing ${icon('chevron')}</button>` : `<button class="btn green" data-route="reels">Explore Reels →</button>`}</div></div>` }
        const remaining = t => Math.max(1, Math.ceil((86400000 - (Date.now() - t)) / 3600000)) + 'h';
        function explore() { const all = [...marketPosts(), ...listings]; let filtered = all.filter(x => (state.category === 'All' || state.category === 'Fitness' && x.tag === 'Fitness' || x.category === state.category) && `${x.title} ${x.owner} ${x.area} ${x.tag || ''}`.toLowerCase().includes(state.search.toLowerCase()) && (!state.onlyFavorites || state.likes.includes(x.id))); if (state.sortBy === 'low') filtered.sort((a, b) => a.price - b.price); if (state.sortBy === 'high') filtered.sort((a, b) => b.price - a.price); if (state.sortBy === 'az') filtered.sort((a, b) => a.title.localeCompare(b.title)); return `<div class="page-heading"><div class="eyebrow">Explore the local marketplace</div><h1>Discover what’s around you.</h1><p>Shop example rentals, workers, creative services and enterprise operations in a photo-forward layout.</p></div><form class="search-main" id="explore-search">${icon('search')}<input id="explore-query" aria-label="Search listings" placeholder="Search gear, people, categories…" value="${esc(state.search)}"><button class="btn green">Search</button></form><section class="section"><div class="category-quick"><button data-category="All" class="${state.category === 'All' ? 'chosen' : ''}">${images('hero', 'alt="All categories"')}<span>Everything</span></button>${cats.map(([id, t, img]) => `<button data-category="${id}" class="${state.category === id ? 'chosen' : ''}">${images(img, `alt="${esc(t)}"`)}<span>${esc(t)}</span></button>`).join('')}</div><div class="market-toolbar"><div class="filter-pills"><button class="filter-pill ${state.onlyFavorites ? 'selected' : ''}" data-toggle-favorites>${icon('heart')} Saved favorites (${state.likes.length})</button><button class="filter-pill" data-save-search>${icon('sparkle')} Save this search</button></div><label class="sort-label">Sort <select id="sort-select" aria-label="Sort listings">${[['featured', 'Featured'], ['low', 'Price: low first'], ['high', 'Price: high first'], ['az', 'Name: A–Z']].map(([v, l]) => `<option value="${v}" ${state.sortBy === v ? 'selected' : ''}>${l}</option>`).join('')}</select></label></div>${state.savedSearches.length ? `<div class="saved-searches"><span>Saved searches</span>${state.savedSearches.map((x, i) => `<button data-load-search="${i}">${icon('search')} ${esc(x.name)}</button>`).join('')}</div>` : ''}<div class="section-head"><div><h2>${state.onlyFavorites ? 'Your favorites' : state.category === 'All' ? 'Featured marketplace' : esc(state.category) + ' listings'}</h2><p>${filtered.length} ${filtered.length === 1 ? 'listing' : 'listings'} · illustrative availability</p></div><button class="btn outline small" data-route="post">${icon('plus')} Post an item / request</button></div><div class="listing-grid">${filtered.map(listingCard).join('') || '<div class="empty">No matching listings. Try another category, search or favorites filter.</div>'}</div></section>` }
        function reelsPage() { const entries = stories(); return `<div class="page-heading"><div class="eyebrow">Short-form marketplace discovery</div><h1>Nearby Reels.</h1><p>Watch a local stylist, trainer, handyman or enterprise provider in action. Created Reels stay visible for 24 hours.</p></div>${storiesStrip()}<div class="section-head"><div><h2>Watch the local edit</h2><p>Examples are permanently available as an illustration. Your created Reels expire after 24 hours.</p></div><button class="btn gold" data-scroll="upload-reel">${icon('plus')} Create a Reel</button></div><div class="reel-feed-grid">${entries.map(r => `<button class="reel-tile" data-reel="${esc(r.id)}">${r.media ? `<img src="${r.media}" alt="${esc(r.title)}">` : images(r.image, `alt="${esc(r.title)}"`)}<span class="reel-view-icon">${icon('play')}</span><span class="ttl">${r.source === 'user' ? remaining(r.created) + ' left' : 'SAMPLE'}</span><div><strong>${esc(r.title)}</strong><small>${esc(r.author)} · ${esc(r.category)}</small></div></button>`).join('')}</div><div id="upload-reel" class="section"><div class="panel"><div class="eyebrow">24-hour promotion</div><h2 style="font:600 30px var(--serif);color:#004f46;margin:7px 0 9px">Show what you're working on.</h2><p class="muted">Share an outfit, a workout, a before-and-after job, or enterprise project. The local demo only stores your post in this browser.</p>${!paid() ? `<div class="upgrade-box"><div><strong>Publishing requires a paid membership.</strong><div class="muted tiny">Free accounts can watch. Trade, Business and Enterprise can create promotional Reels.</div></div><button class="btn gold" data-route="membership">Unlock posting</button></div>` : `<form id="reel-form" class="form-grid" style="margin-top:14px"><div class="field"><label for="reel-title">Reel title</label><input id="reel-title" name="title" maxlength="80" required placeholder="A new listing, a workout, a finished job…"></div><div class="field"><label for="reel-category">Category</label><select id="reel-category" name="category">${['Fashion', 'Fitness', 'Home services', 'Equipment', 'Creators', 'Enterprise', 'Events', 'Outdoor'].map(x => `<option>${x}</option>`).join('')}</select></div><div class="field"><label for="reel-caption">What are you showing?</label><textarea id="reel-caption" name="caption" required maxlength="300" placeholder="Tell people what makes this moment worth checking out"></textarea></div><div class="field"><label for="reel-file">Photo or short video</label><input id="reel-file" name="media" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" required><div class="tiny muted">Browser demo: files up to 1.5 MB. No public upload or hosting.</div></div><label class="checkbox-line" style="grid-column:1/-1"><input type="checkbox" name="consent" required> I have permission to publish the media and identifiable people shown, and I understand this demo stores the post only in my browser.</label><button type="submit" class="btn gold">Publish a 24-hour demo Reel →</button></form>`}</div></div>` }
        function postPage() { return `<div class="page-heading"><div class="eyebrow">Make a connection</div><h1>What would you like to post?</h1><p>Free accounts can post eligible requests. Active paid accounts can also offer rentals and services.</p></div><div class="panel"><form id="post-form"><div class="form-grid"><div class="field"><label for="post-kind">What are you posting?</label><select name="kind" id="post-kind"><option value="request">I need something / request a service (free)</option><option value="rental">List an item to rent or sell (paid)</option><option value="service">Offer my skills or services (paid)</option><option value="business">Enterprise listing (paid team access)</option></select></div><div class="field"><label for="post-category">Category</label><select id="post-category" name="category">${cats.map(([c, t]) => `<option value="${c}">${t}</option>`).join('')}</select></div><div class="field"><label for="post-title">Title</label><input id="post-title" name="title" required maxlength="90" placeholder="What are you looking for or offering?"></div><div class="field"><label for="post-price">Budget or asking price (USD)</label><input id="post-price" name="price" required type="number" min="0" step="1" placeholder="75"></div><div class="field"><label for="post-area">Approximate service area</label><input id="post-area" name="area" required maxlength="45" value="Frisco"></div><div class="field"><label for="post-date">Preferred date</label><input id="post-date" name="date" type="date"></div></div><div class="field"><label for="post-description">Details</label><textarea id="post-description" name="description" required minlength="10" maxlength="750" placeholder="Add useful details, condition, expectations, or what you need help with."></textarea></div><label class="checkbox-line"><input type="checkbox" name="permission" required> I have the right to post this information. I understand this demonstration does not publish to a public marketplace.</label><div class="spaced"><button type="submit" class="btn green">Save demo post →</button><span class="tiny muted">No live audience or payment is connected.</span></div></form></div>${state.posts.length ? `<section class="section"><div class="section-head"><div><h2>Your demo posts</h2></div></div><div class="panel"><table class="data-table"><thead><tr><th>Post</th><th>Type</th><th>Budget</th><th></th></tr></thead><tbody>${state.posts.map(p => `<tr><td>${esc(p.title)}</td><td>${esc(p.type)}</td><td>$${p.price}</td><td><button class="btn small outline" data-remove-post="${p.id}">Remove</button></td></tr>`).join('')}</tbody></table></div></section>` : ''}` }
        function messagesPage() { if (!paid()) return `<div class="page-heading"><h1>Messages & offers.</h1><p>Messaging is a paid member capability in this IDLE concept.</p></div><div class="upgrade-box"><div><strong>Browse free. Communicate with a paid account.</strong><div class="tiny muted">Trade, Business and Enterprise unlock paid messaging and eligible earning tools.</div></div><button class="btn gold" data-route="membership">Compare plans →</button></div><div class="section panel" style="margin-top:18px"><h3>While browsing for free, you can:</h3><p>Explore listings, save favorites, and submit eligible requests without contacting a provider directly.</p></div>`; return `<div class="page-heading"><h1>Inbox & negotiations.</h1><p>Local demonstration messages only. No other participant receives your text.</p></div>${state.inbox.length ? `<div class="panel">${state.inbox.map((m, i) => `<div style="padding:16px;border-bottom:1px solid #e4ede7"><strong>${esc(m.subject)}</strong><span class="status demo" style="margin-left:8px">DEMO SENT</span><p>${esc(m.text)}</p><small class="muted">Your draft to ${esc(m.to)} · ${new Date(m.at).toLocaleString()}</small></div>`).join('')}</div>` : '<div class="empty"><h3>No messages yet</h3><p>Open any example listing and choose “Message provider” to compose a simulated outbound message.</p><button class="btn green" data-route="explore">Explore listings</button></div>'}` }
        function transactionsPage() { return `<div class="page-heading"><h1>Bookings & transaction records.</h1><p>Illustrative booking stages. No payment holds, charges, QR authorization or real agreements occur.</p></div>${state.bookings.length ? `<div class="panel"><table class="data-table"><thead><tr><th>Item</th><th>Amount</th><th>Demo status</th><th></th></tr></thead><tbody>${state.bookings.map(b => { let x = getListing(b.itemId); return `<tr><td>${esc(x?.title || 'Listing')}<br><small class="muted">${new Date(b.created).toLocaleDateString()}</small></td><td>$${esc(b.price)}</td><td><span class="status ${b.stage === 'Draft' ? 'pending' : 'demo'}">${esc(b.stage)}</span></td><td><button data-booking="${b.id}" class="btn small outline">Open →</button></td></tr>` }).join('')}</tbody></table></div>` : '<div class="empty"><h3>Nothing booked yet</h3><p>Select a listing, then choose “Start booking demo” to see a record move from request through return or completion.</p><button class="btn green" data-route="explore">Explore marketplace</button></div>'}<section class="section"><div class="panel"><strong>What an IDLE transaction will support</strong><p class="muted tiny">Offers, acceptance records, condition photos, agreed timing, fee approval, QR handoffs, completion, reviews, issue evidence and independent referral. This preview simulates transitions and does not authorize any funds or provider actions.</p></div></section>` }
        function enterprisePage() { const eligible = ['Business', 'Enterprise'].includes(state.plan); return `<div class="page-heading"><div class="eyebrow">Business & enterprise</div><h1>One workspace for teams, equipment and projects.</h1><p>Coordinate inventory, field workers, vendor access, scheduling and internal approvals. All accounts below are demonstration records.</p></div><div class="stats"><div class="stat"><b>10</b><span>Baseline named Enterprise seats</span></div><div class="stat"><b>$90</b><span>Proposed monthly enterprise baseline</span></div><div class="stat"><b>${state.enterpriseTasks.length}</b><span>Local demo assignments</span></div><div class="stat"><b>${state.enterpriseTeam.length}</b><span>Demo team members added</span></div></div><section class="section"><div class="section-head"><div><h2>Enterprise service lanes</h2></div><button class="btn gold" data-route="membership">Membership & permissions</button></div><div class="enterprise-cards">${[['Workforce & field operations', 'Coordinate people and job handoffs.', 'workers'], ['Equipment & fleet', 'Equipment calendars and custodian records.', 'excavator'], ['Events & hospitality', 'Event crews, spaces and scheduled inventory.', 'events'], ['Corporate & coworking', 'Reserve meeting rooms and workspaces.', 'office'], ['Facilities operations', 'Manage repairs, vendor assignments and tasks.', 'handyman'], ['Business creative services', 'Source creators, equipment and production support.', 'creator']].map(([h, p, img]) => `<article class="enterprise-card">${images(img, `alt="${esc(h)}" loading="lazy"`)}<div><strong>${esc(h)}</strong><p>${esc(p)}</p><button class="btn outline small" data-category="Enterprise">Explore examples →</button></div></article>`).join('')}</div></section><section class="section enterprise-workspace"><div class="section-head"><div><div class="eyebrow">Operations dashboard</div><h2>Seats, dispatch and approvals</h2><p>Try the enterprise workbench. Invitations and assignments stay inside this browser.</p></div></div>${!eligible ? `<div class="upgrade-box"><div><strong>Preview an organizational plan to use the workbench.</strong><div class="muted tiny">Company approvals and role-based access must be enforced by a server in production.</div></div><button class="btn gold" data-route="membership">Choose Business / Enterprise</button></div>` : `<div class="dash-grid"><div class="panel"><h3>Add a team member</h3><form id="team-form"><div class="field"><label for="team-name">Display name</label><input id="team-name" name="name" required maxlength="60" placeholder="Sam · Field operations"></div><div class="field"><label for="team-role">Assigned role</label><select id="team-role" name="role">${['Owner / admin', 'Dispatcher', 'Provider / driver', 'Inventory manager', 'Viewer'].map(x => `<option>${x}</option>`).join('')}</select></div><button class="btn green">Add demo team member</button></form><div class="line"></div><h3>Demo team (${state.enterpriseTeam.length})</h3>${state.enterpriseTeam.length ? state.enterpriseTeam.map(m => `<div class="team-row"><div><strong>${esc(m.name)}</strong><small>${esc(m.role)} · no invitation sent</small></div><button data-remove-team="${m.id}" aria-label="Remove team member">${icon('x')}</button></div>`).join('') : '<p class="muted tiny">No team members added yet. Enterprise role names and permissions are illustrative.</p>'}</div><div class="panel"><h3>Dispatch a task</h3><form id="enterprise-task-form"><div class="field"><label for="task-title">Task or project</label><input id="task-title" name="title" required maxlength="90" placeholder="Equipment handoff at north site"></div><div class="field"><label for="task-assignee">Assign to</label><select id="task-assignee" name="assignee"><option value="Unassigned">Unassigned</option>${state.enterpriseTeam.map(m => `<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="task-date">Target date</label><input id="task-date" name="date" type="date"></div><button class="btn green">Create demo assignment</button></form><div class="line"></div><h3>Tasks (${state.enterpriseTasks.length})</h3>${state.enterpriseTasks.length ? state.enterpriseTasks.map(t => `<div class="team-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.assignee)} · ${esc(t.date || 'Date not set')} · ${esc(t.status)}</small></div><button class="btn outline small" data-complete-task="${t.id}">${t.status === 'Done' ? 'Done ✓' : 'Complete'}</button></div>`).join('') : '<p class="muted tiny">Create a task to preview role-assigned operations.</p>'}</div></div>`}</section><section class="section"><div class="panel"><h3>Permission design</h3><p class="muted tiny">Owner/admin, dispatcher, provider/driver, inventory manager and viewer are separate server-enforced roles in the production plan. A local demo change cannot grant live access or notify outside people.</p></div></section>` }
        function resourcesPage() { const stats = `<div class="resource-metrics"><span>${state.bookings.length} <small>Booking records</small></span><span>${state.posts.length} <small>Local posts</small></span><span>${state.cases.length} <small>Issue records</small></span><span>${state.reviews.length} <small>Reviews</small></span></div>`; return `<div class="page-heading"><div class="eyebrow">Account control center</div><h1>Tools & Resources.</h1><p>Manage everything from membership and records to safety, consent and independent resolution referrals.</p></div>${stats}<div class="resource-grid">${resourceItems.map(([name, ic, description], i) => `<button class="resource" data-resource="${i}"><span class="resource-icon">${icon(ic)}</span><span><strong>${name}</strong><small>${description}</small></span>${icon('chevron')}</button>`).join('')}</div><section class="section"><div class="panel"><h3>Support and safety</h3><p class="muted">IDLE organizes communication and records. Identity checks, payment services, protection plans and independent arbitration require approved providers, applicable consent, and specific terms. In an emergency, contact appropriate emergency services directly.</p><div class="spaced"><button class="btn outline" data-export>${icon('download')} Export demo activity</button><button class="btn outline" data-route="transactions">View transaction records →</button></div></div></section>` }
        function membershipPage() {
            return `<div class="page-heading"><div class="eyebrow">Participation & permissions</div><h1>Choose how you use IDLE.</h1><p>Preview roles and features. Changing the demo plan is not a subscription purchase.</p></div><div class="notice" style="margin-bottom:15px">Your active demo mode: <strong>${esc(state.plan)}</strong>. Pricing below is proposal information from the blueprint, not an active billing offer.</div><div class="plan-grid">${[
                ['Free', '$0', 'Browse local items and services, save favorites, and publish eligible requests. No messaging or earning listings.', ['Browse items and Reels', 'Post an eligible request', 'No communication or paid offers']],
                ['Trade', '$19.99', 'For individuals promoting gear and professional skills.', ['Paid messaging and offers', 'Up to eight active earning listings', 'Five-day proposed trial']],
                ['Business', 'TBD', 'For companies needing business profiles, inventory and client-facing services.', ['Business listing tools', 'Team and inventory concepts', 'Pricing requires confirmation']],
                ['Enterprise', '$90', 'Baseline monthly proposal for teams with multiple authorized seats.', ['Ten named seats baseline', 'Role-specific approvals and dispatch', 'More eligible listings, fair use']]
            ].map(([name, price, desc, features]) => `<article class="plan-card ${name === state.plan ? 'featured' : ''}"><div class="plan-name">${name}</div><div class="plan-price">${price}<small>${price.startsWith('$') ? '/month' : ''}</small></div><p>${desc}</p><ul>${features.map(f => `<li>${f}</li>`).join('')}</ul><button class="btn ${name === state.plan ? 'outline' : 'green'}" data-set-plan="${name}">${name === state.plan ? 'Current demo mode' : 'Preview ' + name}</button></article>`).join('')}</div><p class="caution" style="margin-top:16px">A real membership requires signup, payment consent, billing disclosures, permission enforcement on the server, and approval of the final Business/Enterprise registry. Existing agreements must remain accessible if a plan expires.</p>`
        }
        function onboardingPage() { const n = Math.min(4, Math.max(1, Number(state.onboardingStep) || 1)); return `<div class="page-heading"><div class="eyebrow">Get started with IDLE</div><h1>Make your community work for you.</h1><p>A guided local preview of account setup. No real credentials, verification, subscription or email are created.</p></div><div class="onboarding-track">${[['01', 'Basics'], ['02', 'Participation'], ['03', 'Profile'], ['04', 'Tools']].map(([no, name], i) => `<button class="onboarding-point ${n === i + 1 ? 'current' : ''} ${n > i + 1 ? 'finished' : ''}" data-onboard-step="${i + 1}"><span>${n > i + 1 ? '✓' : no}</span><strong>${name}</strong></button>`).join('')}</div><div class="panel onboarding-panel">${n === 1 ? `<div class="eyebrow">Stage 1 / Account basics</div><h2>Welcome to IDLE.</h2><p class="muted">You can explore freely. To practice a customer profile, choose a display name and approximate area.</p><form id="onboarding-basics"><div class="form-grid"><div class="field"><label for="onboard-name">Display name</label><input id="onboard-name" name="name" required maxlength="45" value="${esc(state.name === 'Guest member' ? '' : state.name)}" placeholder="Your display name"></div><div class="field"><label for="onboard-area">Approximate area</label><input id="onboard-area" name="area" required maxlength="60" value="${esc(state.profileArea || 'Frisco')}" placeholder="City or neighborhood (not exact address)"></div></div><label class="checkbox-line"><input type="checkbox" name="adult" required> I confirm I meet the platform's stated age eligibility requirements.</label><label class="checkbox-line"><input type="checkbox" name="terms" required> I agree to the demonstration terms, consent notices and privacy information shown here. No actual account is created.</label><button class="btn green">Continue to participation →</button></form>` : n === 2 ? `<div class="eyebrow">Stage 2 / Participation</div><h2>Choose how you participate.</h2><p class="muted">Free browsing and eligible requests; Trade, Business and Enterprise offer additional demo permissions.</p><div class="onboarding-plans">${[['Free', '$0', 'Browse and request. No messaging.'], ['Trade', '$19.99 / mo', 'Individual provider tools and messaging.'], ['Business', 'Pricing TBD', 'Business profiles and inventory.'], ['Enterprise', '$90 / mo baseline', 'Teams, seats, approvals and dispatch.']].map(([plan, cost, desc]) => `<button class="onboarding-plan ${state.plan === plan ? 'selected' : ''}" data-set-plan="${plan}"><strong>${plan}</strong><b>${cost}</b><small>${desc}</small></button>`).join('')}</div><button class="btn green" data-onboard-step="3">Continue to profile →</button><p class="caution">These are preview permissions, not live subscriptions. Membership may require billing and verification before activation.</p>` : n === 3 ? `<div class="eyebrow">Stage 3 / Profile</div><h2>Show what you do.</h2><p class="muted">A short profile helps future marketplace participants understand what you offer or need.</p><form id="onboarding-profile"><div class="field"><label for="onboard-skills">Skills, interests, or services</label><textarea id="onboard-skills" name="skills" maxlength="260" placeholder="Photography, equipment rentals, event support…">${esc(state.skills)}</textarea></div><div class="field"><label for="onboard-availability">General availability</label><select name="availability" id="onboard-availability">${['Flexible', 'Weekdays', 'Weekends', 'By appointment'].map(x => `<option ${x === state.availability ? 'selected' : ''}>${x}</option>`).join('')}</select></div><button class="btn green">Continue to tools →</button></form>` : `<div class="eyebrow">Stage 4 / Helpful tools</div><h2>You're ready to explore.</h2><p class="muted">Preferences can be changed later. No external tools or payment accounts are connected.</p><form id="onboarding-tools"><label class="checkbox-line"><input type="checkbox" name="notifications" ${state.notificationOptIn ? 'checked' : ''}> Opt in to future demonstration notifications (no messages are sent).</label><div class="onboarding-tool-rows"><div>${icon('wallet')} <strong>Payments & payouts</strong> <small>Connect only when a real processor integration is available.</small></div><div>${icon('shield')} <strong>Identity & credentials</strong> <small>Require specific vendor consent and payer approval.</small></div><div>${icon('calendar')} <strong>Availability</strong> <small>Your demo preference: ${esc(state.availability)}.</small></div></div><button class="btn gold">Finish and explore marketplace →</button></form>`}</div>` }
        function profilePage() { return `<div class="page-heading"><h1>Account & profile.</h1><p>Profile data and sample activity saved locally to this browser.</p></div><div class="dash-grid"><div class="panel"><div class="spaced" style="margin-bottom:18px"><span class="user-avatar" style="width:58px;height:58px;font-size:22px">${esc(state.name[0])}</span><div><h2 style="font:600 26px var(--serif);color:#004f46;margin:0">${esc(state.name)}</h2><div class="muted tiny">${state.joined ? 'Demo account profile' : 'Guest preview'} · ${esc(state.plan)} membership</div></div></div><form id="profile-form"><div class="field"><label>Display name</label><input name="name" required maxlength="45" value="${esc(state.name)}"></div><div class="field"><label>About you</label><textarea name="bio" maxlength="300" placeholder="Tell your community about your skills or interests">${esc(state.bio || '')}</textarea></div><button class="btn green">Save profile locally</button></form></div><div class="panel"><h3>Demo account overview</h3><p>Current permissions: <strong>${paid() ? 'Paid member preview' : 'Free preview'}</strong></p><p class="muted tiny">${state.posts.length} posts · ${state.myReels.length} live Reels · ${state.bookings.length} booking records</p><div class="spaced"><button class="btn outline" data-route="onboarding">${state.joined ? 'Edit onboarding' : 'Get started'}</button><button class="btn outline" data-route="membership">Membership</button><button class="btn outline" data-route="resources">Resources</button></div><div class="line"></div><button class="btn ghost" data-export>${icon('download')} Export demo data</button><button class="btn outline" data-clear-demo>Reset demo</button></div></div><section class="section"><div class="panel"><h3>Activity log</h3>${state.events.length ? `<table class="data-table">${state.events.slice(0, 10).map(e => `<tr><td>${new Date(e.at).toLocaleString()}</td><td>${esc(e.message)}</td></tr>`).join('')}</table>` : '<p class="muted">Activities from sample interactions appear here.</p>'}</div></section>` }
        function journeyPage() { return `<div class="page-heading"><div class="eyebrow">Full customer lifecycle</div><h1>From discovery to completed experience.</h1><p>The 15 connected stages in the IDLE journey. Preview-only implementation; live services are not connected.</p></div><div class="steps-grid">${journeySteps.map((step, i) => `<article class="step-card"><b>${String(i + 1).padStart(2, '0')} / 15</b><h3>${step}</h3><p>${['Access and eligibility', 'Roles and plan permissions', 'Profile and interests', 'Checks and preferences', 'Categories and listings', 'Offers and consent', 'Terms and records', 'Authorized payments', 'Schedules and notices', 'Handoff documentation', 'Extensions and changes', 'Condition and receipt', 'Negotiation or independent referral', 'Ratings and moderation', 'Earnings and account controls'][i]}</p><button class="btn outline small" data-route="${['onboarding', 'membership', 'profile', 'resources', 'explore', 'messages', 'transactions', 'transactions', 'transactions', 'transactions', 'transactions', 'transactions', 'resources', 'resources', 'profile'][i]}">Open related screen →</button></article>`).join('')}</div>` }
        function modalBody() {
            if (state.dialog === 'listing') { let l = getListing(state.activeListing); if (!l) return ''; return `<div class="mini-modal" id="dialog-surface"><div class="dialog wide" role="dialog" aria-modal="true" aria-label="${esc(l.title)}"><button class="close" data-close-dialog aria-label="Close">${icon('x')}</button><div class="form-grid"><div>${images(l.image, `class="modal-photo" alt="${esc(l.title)}"`)}</div><div><span class="eyebrow">${esc(l.tag)} · ${esc(l.area)}</span><h2>${esc(l.title)}</h2><p class="muted">Example provider: ${esc(l.owner)}</p><h3 style="font-size:24px;color:#004f46">$${l.price} <small style="font-size:13px">/ ${esc(l.unit)}</small></h3><p class="muted">${esc(l.desc)}</p><div class="notice">Illustrative listing. Pricing, availability, identity and credentials are not verified. No real booking is created.</div><div class="modal-actions"><button class="btn green" data-start-booking="${l.id}">${icon('calendar')} Start booking demo</button><button class="btn outline" data-message-listing="${l.id}">${icon('message')} Message provider</button></div><div class="muted tiny" style="margin-top:10px">Free browsing and eligible requests are allowed. Provider messaging needs a paid account.</div></div></div></div></div>` }
            if (state.dialog === 'resource') { const item = resourceItems[state.resourceIndex]; if (!item) return ''; const idx = state.resourceIndex; const routes = ['membership', 'transactions', 'profile', 'post', 'messages', 'transactions', 'transactions', 'resources', 'transactions', 'transactions', 'profile']; const line = idx === 8 ? `<div class="subtle-box"><strong>Independent remote resolution</strong><p>Direct negotiation comes first. An external mediator or arbitrator must be selected under suitable jurisdiction, pricing, data-transfer consent and provider terms. No dispute evidence is sent in this demo.</p><strong>${state.cases.length} locally recorded issue(s)</strong></div>` : idx === 1 ? `<div class="subtle-box"><strong>Payments & receipts</strong><p>${state.bookings.length} booking draft(s). All amounts are illustrations. No actual charge, payout or hold was created.</p></div>` : idx === 9 ? `<div class="subtle-box">${state.reviews.length} locally recorded reviews. Reviews require a completed eligible booking.</div>` : idx === 10 ? `<div class="subtle-box">Your local activity can be exported. This standalone demo is not an authenticated account or a cloud data store.</div>` : `<div class="subtle-box">This module is an interface demonstration. Live provider integrations, credentials and account permissions are not connected.</div>`; return `<div class="mini-modal" id="dialog-surface"><div class="dialog" role="dialog" aria-modal="true" aria-label="Resource details"><button class="close" data-close-dialog aria-label="Close resources">${icon('x')}</button><div class="eyebrow">Tools & Resources · ${idx + 1} / 11</div><h2>${esc(item[0])}</h2><p class="muted">${esc(item[2])}</p><div class="line"></div>${line}<div class="modal-actions"><button class="btn green" data-route="${routes[idx]}">Open related workspace →</button>${idx === 10 ? '<button class="btn outline" data-export>Export my demo data</button>' : ''}<button class="btn outline" data-close-dialog>Close</button></div></div></div>` }
            if (state.dialog === 'message') { let l = getListing(state.activeListing); if (!l) return ''; return `<div class="mini-modal" id="dialog-surface"><div class="dialog" role="dialog" aria-modal="true" aria-label="Message provider"><button class="close" data-close-dialog>${icon('x')}</button><div class="eyebrow">In-app communication</div><h2>Message ${esc(l.owner)}</h2>${paid() ? `<p class="muted">Only a local demonstration. This message will not be delivered.</p><form id="message-form"><div class="field"><label>Your message</label><textarea name="message" required minlength="3" placeholder="Hi! Is this available for my dates?"></textarea></div><button class="btn green">Save message draft →</button></form>` : `<p class="muted">Messaging requires a paid Trade, Business or Enterprise account.</p><button class="btn gold" data-route="membership">Compare memberships</button>`}</div></div>` }
            if (state.dialog === 'booking') {
                const b = state.bookings.find(x => x.id === state.activeBooking), l = getListing(b?.itemId); if (!b || !l) return ''; const i = bookingStages.indexOf(b.stage), view = state.bookingView || 'timeline'; const actions = `<div class="modal-actions booking-actions"><button class="btn outline" data-booking-view="timeline">Timeline</button>${i < 4 ? '<button class="btn outline" data-booking-view="extension">Request a change</button>' : ''}<button class="btn outline" data-booking-view="issue">Report issue</button>${i === 4 ? '<button class="btn gold" data-booking-view="review">Leave a review</button>' : ''}</div>`;
                let pane = '';
                if (view === 'timeline') { pane = `<div class="booking-timeline">${bookingStages.map((step, j) => `<div class="booking-step ${j <= i ? 'done' : ''}"><span>${j < i ? icon('check') : j === i ? icon('clock') : (j + 1)}</span><div><strong>${step}</strong><small>${j === i ? 'Current stage' : j < i ? 'Previewed' : 'Not yet reached'}</small></div></div>`).join('')}</div><div class="booking-notice">Every stage is a local demonstration. It does not create a legally binding agreement, capture a payment, issue a scannable QR code or contact the other participant.</div>${i < 4 ? `<button class="btn green" data-booking-view="confirm">Review ${bookingStages[i + 1]} →</button>` : '<button class="btn gold" data-booking-view="review">Leave demo review →</button>'}` }
                if (view === 'confirm') {
                    const next = bookingStages[i + 1]; const summary = i === 0 ? `<div class="field"><label for="booking-date">Proposed date</label><input type="date" name="date" id="booking-date" value="${esc(b.date || '')}" required></div><div class="field"><label for="booking-time">Proposed time</label><input type="time" name="time" id="booking-time" value="${esc(b.time || '12:00')}" required></div><p>Preview parties: ${esc(state.name)} and ${esc(l.owner)}. Item or service: ${esc(l.title)}. The next step creates a versioned example agreement snapshot.</p>` : i === 1 ? `<div class="contract-sheet"><strong>Example agreement • Version ${b.agreementVersion || 1}</strong><p><b>Parties:</b> ${esc(state.name)} / ${esc(l.owner)}</p><p><b>Scope:</b> ${esc(l.title)} — ${esc(l.desc)}</p><p><b>Price:</b> $${esc(b.price)} per ${esc(l.unit)}</p><p><b>Date:</b> ${esc(b.date || 'Proposed only')} ${esc(b.time || '')}</p><p><b>Cancellation and condition terms:</b> Must be accepted from actual final terms when implemented.</p></div>` : i === 2 ? `<div class="contract-sheet"><strong>Payment review • example only</strong><div class="receipt-row"><span>Listed base price</span><b>$${esc(b.price)}</b></div><div class="receipt-row"><span>Security authorization</span><b>Not configured</b></div><div class="receipt-row"><span>Taxes / processing costs</span><b>Not calculated</b></div><div class="receipt-row"><span>Actual amount charged</span><b>$0.00</b></div><p>Deposit holds are neither guaranteed nor escrow. A production checkout requires explicit payer authorization and actual processor confirmation.</p></div>` : `<div class="contract-sheet"><strong>Handoff / completion preview</strong><div class="handoff-token">IDLE-DEMO-${String(b.id).slice(-6)}</div><p>This is a reference token, not a real QR credential. To confirm a real handoff, both parties must record custody and condition, supported by actual authenticated events.</p><div class="field"><label for="booking-condition">Item condition or job completion notes</label><textarea id="booking-condition" name="condition" required minlength="8" placeholder="Describe pickup, handoff or completed work"></textarea></div><div class="field"><label for="booking-photo">Optional evidence photo (small local demo)</label><input type="file" id="booking-photo" name="photo" accept="image/jpeg,image/png,image/webp"></div></div>`;
                    pane = `<h3 class="booking-subtitle">${next}</h3><form id="booking-step-form"><input type="hidden" name="bookingId" value="${b.id}">${summary}<label class="checkbox-line"><input type="checkbox" name="acknowledge" required> I understand this is a demonstration; no agreement, charge, handoff or provider confirmation occurs.</label><div class="modal-actions"><button class="btn green">Record demo step →</button><button type="button" class="btn outline" data-booking-view="timeline">Back</button></div></form>`
                }
                if (view === 'extension') pane = `<h3 class="booking-subtitle">Propose a change</h3><p class="muted">Extensions and changes must be re-approved by the parties. This form saves a local request only.</p><form id="booking-change-form"><input name="bookingId" type="hidden" value="${b.id}"><div class="field"><label for="change-request">Requested modification</label><textarea id="change-request" name="request" required minlength="8" placeholder="Extend through Friday, change pickup place, update scope…"></textarea></div><button class="btn green">Save proposed change</button></form>`;
                if (view === 'issue') pane = `<h3 class="booking-subtitle">Create an issue record</h3><p class="muted">Describe the concern and proposed remedy. IDLE documents communications; independent mediators or arbitrators act under their own agreements.</p><form id="booking-issue-form"><input name="bookingId" type="hidden" value="${b.id}"><div class="field"><label for="issue-kind">Preferred path</label><select name="path" id="issue-kind"><option value="Direct negotiation">Discuss with the other party</option><option value="Independent referral inquiry">Explore independent remote mediation / arbitration</option></select></div><div class="field"><label for="issue-text">What happened?</label><textarea name="description" id="issue-text" required minlength="15" placeholder="Describe the disputed facts and relevant evidence"></textarea></div><div class="field"><label for="issue-remedy">Requested resolution</label><input name="remedy" id="issue-remedy" maxlength="140" required placeholder="Return item, propose refund, repair costs…"></div><label class="checkbox-line"><input type="checkbox" name="authority" required> I understand this does not automatically contact another party, freeze money or send evidence to a third party.</label><button class="btn green">Save issue record</button></form>${state.cases.filter(c => c.bookingId === b.id).map(c => `<div class="subtle-box" style="margin-top:12px"><b>${esc(c.path)}</b> · ${esc(c.status)}<p>${esc(c.description)}</p><small>Requested: ${esc(c.remedy)}</small></div>`).join('')}`;
                if (view === 'review') pane = `<h3 class="booking-subtitle">Review your experience</h3>${i !== 4 ? '<p>Reviews become eligible after the completion stage.</p>' : `<form id="booking-review-form"><input name="bookingId" type="hidden" value="${b.id}"><div class="field"><label for="review-stars">Your rating</label><select name="rating" id="review-stars">${[5, 4, 3, 2, 1].map(n => `<option value="${n}">${n} star${n !== 1 ? 's' : ''}</option>`).join('')}</select></div><div class="field"><label for="review-body">Review text</label><textarea name="text" id="review-body" required minlength="8" maxlength="400" placeholder="How did the rental or service go?"></textarea></div><button class="btn green">Save demo review</button></form>`}${state.reviews.filter(r => r.bookingId === b.id).map(r => `<div class="subtle-box" style="margin-top:12px">★ ${r.rating}/5 · ${esc(r.text)}</div>`).join('')}`;
                return `<div class="mini-modal" id="dialog-surface"><div class="dialog wide booking-dialog" role="dialog" aria-modal="true" aria-label="Transaction demo"><button class="close" data-close-dialog aria-label="Close transaction">${icon('x')}</button><span class="eyebrow">IDLE transaction center · local preview</span><div class="booking-header"><div><h2>${esc(l.title)}</h2><p>Listed amount: <strong>$${esc(b.price)}</strong> · ${esc(l.owner)}</p></div><span class="status demo">${esc(b.stage)}</span></div>${actions}<div class="line"></div>${pane}${b.evidencePhoto ? `<details class="history-details"><summary>Attached local condition photo</summary><img src="${b.evidencePhoto}" alt="Locally saved condition evidence" style="width:200px;max-width:100%;margin:10px 0;border-radius:10px"></details>` : ''}${b.history?.length ? `<details class="history-details"><summary>Activity history (${b.history.length})</summary>${b.history.map(x => `<p>${new Date(x.at).toLocaleString()} · ${esc(x.message)}</p>`).join('')}</details>` : ''}</div></div>`
            }
            return ''
        }
        function render() { cleanReels(); const content = { home, onboarding: onboardingPage, explore, reels: reelsPage, post: postPage, messages: messagesPage, transactions: transactionsPage, enterprise: enterprisePage, resources: resourcesPage, membership: membershipPage, profile: profilePage, journey: journeyPage }[state.route] || home; const viewer = !!getStory(); $('#app').innerHTML = chrome(`<main class="page shell"><div class="body-with-reel ${viewer ? 'reel-open' : ''}"><div class="page-main">${content()}</div>${viewer ? `<aside class="reel-drawer" id="reel-drawer">${reelDrawer()}</aside>` : ''}</div></main>${modalBody()}`); queueHD(); }
        function openReel(id) { state.reelId = id; save(); render(); if (innerWidth <= 960) document.body.style.overflow = 'hidden'; }
        function closeReel() { state.reelId = null; document.body.style.overflow = ''; save(); render() }
        function cycleReel(delta) { const xs = stories(); const i = xs.findIndex(x => x.id === state.reelId); if (i === -1) return; state.reelId = xs[(i + delta + xs.length) % xs.length].id; save(); render() }
        function openListing(id) { const l = getListing(id); if (!l) return; state.dialog = 'listing'; state.activeListing = l.id; save(); render() }
        function openMessage(id) { state.dialog = 'message'; state.activeListing = Number(id); save(); render() }
        function openBooking(id) { state.dialog = 'booking'; state.activeBooking = Number(id); state.bookingView = 'timeline'; save(); render() }
        function formValues(f) { return Object.fromEntries(new FormData(f).entries()) }
        async function saveReel(form) { if (!paid()) { toast('Paid membership is required for self-promotion.'); return } let fd = new FormData(form), file = fd.get('media'); if (!(file instanceof File) || file.size === 0) { toast('Choose a photo or short video.'); return } if (file.size > 1500000) { toast('This standalone demo supports media up to 1.5 MB.'); return } if (!['image/jpeg', 'image/png', 'image/webp', 'video/mp4', 'video/webm'].includes(file.type)) { toast('Please select a JPG, PNG, WebP, MP4 or WebM file.'); return } if (fd.get('consent') !== 'on') { toast('Please confirm your right to post this media.'); return } const read = await new Promise((resolve, reject) => { const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file) }); let reel = { id: Date.now() + '', title: String(fd.get('title')).slice(0, 80), caption: String(fd.get('caption')).slice(0, 300), author: state.name, category: String(fd.get('category')), area: 'Your area', created: Date.now(), media: read, isVideo: file.type.startsWith('video/') }; state.myReels.unshift(reel); if (!save()) { state.myReels.shift(); return } log('Created a local 24-hour Reel'); state.reelId = 'user:' + reel.id; setRoute('reels'); toast('Demo Reel created. It expires 24 hours after posting.') }
